  `sup_state` int DEFAULT '0',
  `sup_cntry_code` int DEFAULT '0',
  `sup_zip` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_phone` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_fax` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_email` varchar(80) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
