  `sup_led_code` int DEFAULT '0',
  `sup_grp_code` int DEFAULT '0',
  `sup_type` char(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_acc_group` int DEFAULT '0',
  `sup_taxcode` int DEFAULT '0',
  `sup_agentcode` int DEFAULT '0',
  `sup_contact` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_area` int DEFAULT '0',
  `sup_panno` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_tinno` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_sertax_rcno` varchar(25) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_excise_rcno` varchar(25) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
  `sup_tds_type` smallint DEFAULT '0',
  `sup_gstin` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci DEFAULT '',
