  `sup_distance` smallint DEFAULT '0',
  PRIMARY KEY (`sup_code`,`sup_refname`,`seqno`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;
